script:
(function () {
  'use strict';
  // Futures daily mark-to-market (daily settlement) of one position held over a price series.
  //   Each day: variation margin = (settle_t - settle_(t-1)) x multiplier x contracts x (+1 long,
  //   -1 short), with settle_0 = the trade price. Balance += variation margin.
  //   If the balance falls below the maintenance margin (per contract x contracts), a margin call
  //   asks for enough cash to bring it back up to the initial margin (not just maintenance):
  //   call = initial requirement - balance. "Meet calls": the cash is deposited the same day.
  //   "Close out": the position is closed at that day's settlement and later days are ignored.
  //   Check: ending balance = cash put in + total gain/loss.
  // Verified (scratchpad b7opt/tests/fm.test.js), by hand: the default long 2 x 1,000 at 75.00,
  //   $6,000 initial / $5,000 maintenance: day 2 balance $9,300 -> call $2,700; day 5 $8,500 ->
  //   call $3,500; ending balance $20,400 = $18,200 put in + $2,200 gain (= 1.10 x 2,000);
  //   the textbook gold example (long 2 x 100 oz at $1,250, $6,000 / $4,500 per contract, 16
  //   settlement prices) gives calls of $4,020 (day 7) and $3,780 (day 11) and an ending balance of
  //   $15,180 = $19,800 put in - $4,620 loss, worked by hand; a short position mirrors the long.
  var MAX_DAYS = 1000;
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var priceFmt = new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 6 });

  function raw(id) { return document.getElementById(id).value.trim(); }
  function num(id) { var v = parseFloat(raw(id)); return isNaN(v) ? NaN : v; }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }
  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); });
    body.appendChild(tr);
  }
  function signedMoney(x) {
    if (Math.abs(x) < 0.005) return money.format(0);
    return (x > 0 ? '+' : '−') + money.format(Math.abs(x));
  }
  function signedPrice(x) {
    if (Math.abs(x) < 1e-9) return '0.00';
    return (x > 0 ? '+' : '−') + priceFmt.format(Math.abs(x));
  }
  function cents(x) { return Math.round(x * 100) / 100; }

  function parsePrices(text) {
    var parts = text.split(/[;\s]+|,\s+/).filter(function (s) { return s !== ''; });
    var out = [];
    for (var i = 0; i < parts.length; i++) {
      if (!/^\$?\d*\.?\d+$/.test(parts[i])) return null;
      out.push(parseFloat(parts[i].replace(/^\$/, '')));
    }
    return out;
  }

  function markToMarket(o) {
    var side = o.side === 'short' ? -1 : 1;
    var initReq = o.initial * o.contracts, maintReq = o.maint * o.contracts;
    var balance = initReq + o.extra, cashIn = balance, cum = 0, prev = o.entry;
    var rows = [], calls = 0, callTotal = 0, low = balance, closedDay = 0;
    for (var d = 0; d < o.prices.length; d++) {
      var p = o.prices[d];
      var vm = cents((p - prev) * o.multiplier * o.contracts * side);
      balance = cents(balance + vm); cum = cents(cum + vm);
      if (balance < low) low = balance;
      var call = 0, before = balance;
      if (balance < maintReq - 0.005) {
        call = cents(initReq - balance);
        if (o.onCall === 'close') { closedDay = d + 1; rows.push({ day: d + 1, price: p, change: p - prev, vm: vm, cum: cum, before: before, call: call, after: balance }); break; }
        calls++; callTotal = cents(callTotal + call); cashIn = cents(cashIn + call); balance = initReq;
      }
      rows.push({ day: d + 1, price: p, change: p - prev, vm: vm, cum: cum, before: before, call: call, after: balance });
      prev = p;
    }
    return { rows: rows, calls: calls, callTotal: callTotal, cashIn: cashIn, ending: balance, cum: cum, low: low, initReq: initReq, maintReq: maintReq, closedDay: closedDay };
  }

  var RESULT_IDS = ['fmPnl', 'fmCalls', 'fmEnding', 'fmCash', 'fmLow', 'fmReturn'];
  function clearResults() {
    RESULT_IDS.forEach(function (id) { set(id, '–'); set(id + 'Note', ''); });
    document.getElementById('fmClosed').hidden = true;
    clearBody('fmDays');
  }

  function update() {
    var error = document.getElementById('fmError');
    var contracts = num('fmContracts'), mult = num('fmMult'), entry = num('fmEntry'), initial = num('fmInitial'),
        maint = num('fmMaint'), extra = raw('fmExtra') === '' ? 0 : num('fmExtra');
    var prices = parsePrices(raw('fmPrices'));
    var problem = '';
    if (isNaN(contracts) || contracts < 1 || contracts > 100000 || Math.round(contracts) !== contracts) problem = 'Enter a whole number of contracts, 1 or more.';
    else if (isNaN(mult) || mult <= 0) problem = 'Enter a contract multiplier above 0 (dollars per 1.00 move in the price).';
    else if (isNaN(entry) || entry < 0) problem = 'Enter the trade price, 0 or more.';
    else if (isNaN(initial) || initial <= 0) problem = 'Enter an initial margin above $0 per contract.';
    else if (isNaN(maint) || maint <= 0 || maint > initial) problem = 'Enter a maintenance margin above $0 and no higher than the initial margin.';
    else if (isNaN(extra) || extra < 0) problem = 'Enter extra cash of $0 or more.';
    else if (prices === null) problem = 'Daily prices must be numbers separated by a comma and a space, spaces or new lines, with no thousands separators.';
    else if (!prices.length) problem = 'Enter at least one daily settlement price.';
    else if (prices.length > MAX_DAYS) problem = 'Enter at most ' + MAX_DAYS + ' daily prices.';
    error.hidden = !problem;
    error.textContent = problem;
    if (problem) { clearResults(); return; }

    var r = markToMarket({ side: document.getElementById('fmSide').value, contracts: contracts, multiplier: mult, entry: entry,
      initial: initial, maint: maint, extra: extra, prices: prices, onCall: document.getElementById('fmOnCall').value });
    var days = r.rows.length;
    set('fmPnl', signedMoney(r.cum));
    set('fmPnlNote', 'Sum of the daily variation margin over ' + days + (days === 1 ? ' day.' : ' days.'));
    if (r.closedDay) {
      set('fmCalls', 'Closed out');
      set('fmCallsNote', 'A call for ' + money.format(r.rows[days - 1].call) + ' on day ' + r.closedDay + ' was not met.');
    } else {
      set('fmCalls', money.format(r.callTotal));
      set('fmCallsNote', r.calls ? r.calls + (r.calls === 1 ? ' margin call' : ' margin calls') + ' met by depositing cash.' : 'The balance never fell below maintenance margin.');
    }
    set('fmEnding', money.format(r.ending));
    set('fmEndingNote', r.closedDay ? 'Left in the account when the position was closed.' : (r.ending > r.initReq ? money.format(r.ending - r.initReq) + ' above the initial margin could be withdrawn.' : 'At or below the ' + money.format(r.initReq) + ' initial margin.'));
    set('fmCash', money.format(r.cashIn));
    set('fmCashNote', 'Opening deposit of ' + money.format(r.initReq + extra) + (r.calls ? ' plus margin calls.' : '.'));
    set('fmLow', money.format(r.low));
    set('fmLowNote', 'Maintenance level is ' + money.format(r.maintReq) + '.');
    var ret = r.cum / r.cashIn;
    set('fmReturn', (ret >= 0 ? '+' : '−') + (Math.abs(ret) * 100).toFixed(2) + '%');
    set('fmReturnNote', 'Gain or loss divided by all the cash put in. Notional value at the trade price: ' + money.format(entry * mult * contracts) + '.');

    var closed = document.getElementById('fmClosed');
    closed.hidden = !r.closedDay;
    if (r.closedDay) set('fmClosedText', 'The balance fell to ' + money.format(r.rows[days - 1].before) + ' on day ' + r.closedDay + ', below the ' + money.format(r.maintReq) + ' maintenance level. Without the ' + money.format(r.rows[days - 1].call) + ' deposit, the position is closed at that day’s price and the remaining days are not shown.');

    var tb = clearBody('fmDays');
    r.rows.forEach(function (row) {
      addRow(tb, [String(row.day), priceFmt.format(row.price), signedPrice(row.change), signedMoney(row.vm), signedMoney(row.cum),
        money.format(row.before), row.call ? money.format(row.call) + (r.closedDay === row.day ? ' (not met)' : '') : '–', money.format(row.after)]);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('fmForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
